style.css:
@-moz-document domain("youtube.com") {
/* Set the background on html for better coverage */
  html {
    background: url("https://i.pinimg.com/736x/c5/d2/7e/c5d27e4bd705da2133fe537b881697f1.jpg") repeat top left fixed !important;
    background-size: auto !important;
  }

  /* Make YouTube's main app containers transparent */
  ytd-app,
  ytd-page-manager,
  ytd-watch-flexy,
  ytd-browse,
  tp-yt-app-drawer,
  #background,
  #masthead-container,
  #page-manager,
  #primary,
  #secondary,
  #content {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Light overlay for UI readability (optional) */
  ytd-masthead,
  #guide,
  #chips-wrapper {
    background-color: rgba(255, 255, 255, 0.5) !important;
  }

  /* Remove shadows and other overlays that might cover background */
  ytd-app::before,
  ytd-app::after {
    content: none !important;
    display: none !important;
  }
}
